effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:

vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
#define fragCoord gl_FragCoord.xy

//////////////////////////

//////////////////////////
    void main() {
    if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

    vec2 image_size = getTexSize(inputImg.size);
    vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
    vec2 iMouse = vec2(0.5, 0.5);
    float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

    vec2 TanRyu;
    TanRyu = acScreenNorm; 

    /////////////////////////

	vec4 fragColor;

        vec2 uv = TanRyu;

        float height = HEI;
        float wave_strength = STR;
        float wave_frequency = FREQ;
        float transparency = TRP;
        float angle = ANG;

        angle *= uv.y/height+angle/1.5; //3D effect
        wave_strength /= 1000.0;
        float wave = sin(10.0*uv.y+10.0*uv.x+wave_frequency*iTime)*wave_strength;
        wave += sin(20.0*-uv.y+20.0*uv.x+wave_frequency*1.0*iTime)*wave_strength*0.5;
        wave += sin(15.0*-uv.y+15.0*-uv.x+wave_frequency*0.6*iTime)*wave_strength*1.3;
        wave += sin(3.0*-uv.y+3.0*-uv.x+wave_frequency*0.3*iTime)*wave_strength*10.0;

        fragColor = texture2DCv(inputImg.texture, vec2(uv.x, uv.y));

        if(uv.y - wave <= height) {
            fragColor = mix(
            mix(
                texture2DCv(inputImg.texture, vec2(uv.x, ((1.0 + angle)*(height + wave) - angle*uv.y + wave))),
                water_color,
                0.6-(0.3-(0.3*uv.y/height))),
            texture2DCv(inputImg.texture, vec2(uv.x + wave, uv.y - wave)),
            transparency-(transparency*uv.y/height)); }

	gl_FragColor = mix(texColor, fragColor, alpha) * texColor.a;
      }
    }
